"""Single customer churn prediction page."""

import streamlit as st

from dashboard.services import get_prediction_service

from dashboard.components import render_header


def render_prediction_result(result, threshold):
    """Display prediction results returned by PredictionService."""

    churn_probability = float(result["churn_probability"])
    risk_score = float(result["risk_score"])
    risk_category = result["risk_category"]
    churn_prediction = int(result["churn_prediction"])

    st.divider()
    st.header("Prediction Results")

    st.caption(
        "Results generated by the persisted Balanced Logistic "
        "Regression model."
    )

    probability_col, risk_col, category_col = st.columns(3)

    with probability_col:
        st.metric(
            "Churn Probability",
            f"{churn_probability:.1%}",
        )

    with risk_col:
        st.metric(
            "Risk Score",
            f"{risk_score:.1f}/100",
        )

    with category_col:
        st.metric(
            "Risk Category",
            str(risk_category),
        )

    st.subheader("Churn Prediction")

    if churn_prediction == 1:
        st.error("Prediction: Customer is likely to churn.")
    else:
        st.success("Prediction: Customer is not classified as likely to churn.")

    st.metric(
        "Classification Threshold",
        f"{threshold:.2f}",
    )

    st.progress(
        min(max(churn_probability, 0.0), 1.0),
        text=f"Estimated churn probability: {churn_probability:.1%}",
    )

    st.info(
        "Interpretation: The churn probability is a model estimate, "
        "not a certainty. The binary prediction uses the selected "
        "classification threshold, while the risk category uses "
        "separate risk-score ranges."
    )

    st.caption(
        "Risk categories: Low [0.00, 0.30), "
        "Moderate [0.30, 0.50), "
        "High [0.50, 0.70), "
        "Critical [0.70, 1.00]."
    )


def render_single_prediction():
    """Render the single customer prediction interface."""

    render_header(
        "Single Customer Prediction",
        "Enter customer details to estimate churn probability "
        "and identify the customer's churn risk category.",
    )

    # ---------------------------------------------------------
    # 1. Load prediction service
    # ---------------------------------------------------------
    try:
        prediction_service = get_prediction_service()
        metadata = prediction_service.metadata

    except (FileNotFoundError, ValueError, OSError) as exc:
        st.error(f"Unable to load the prediction model: {exc}")
        return

    except Exception as exc:
        st.error(f"Unexpected error while loading the model: {exc}")
        return

    threshold = float(metadata["threshold"])

    st.info(
        f"Model: {metadata['algorithm']} | "
        f"Classification threshold: {threshold:.2f}"
    )

    # ---------------------------------------------------------
    # 2. Customer input form
    # ---------------------------------------------------------
    st.header("Customer Information")

    with st.form("single_customer_prediction_form"):

        st.subheader("Customer Profile")

        profile_col1, profile_col2 = st.columns(2)

        with profile_col1:
            credit_score = st.number_input(
                "Credit Score",
                min_value=300,
                max_value=900,
                value=650,
                step=1,
                help="Customer credit score.",
            )

            age = st.number_input(
                "Age",
                min_value=18,
                max_value=100,
                value=35,
                step=1,
            )

            tenure = st.number_input(
                "Tenure (Years)",
                min_value=0,
                max_value=10,
                value=5,
                step=1,
            )

        with profile_col2:
            geography = st.selectbox(
                "Geography",
                options=["France", "Germany", "Spain"],
            )

            gender = st.selectbox(
                "Gender",
                options=["Female", "Male"],
            )

        st.divider()

        st.subheader("Account Information")

        account_col1, account_col2 = st.columns(2)

        with account_col1:
            balance = st.number_input(
                "Account Balance",
                min_value=0.0,
                value=75000.0,
                step=1000.0,
                format="%.2f",
            )

            num_of_products = st.number_input(
                "Number of Products",
                min_value=1,
                max_value=4,
                value=1,
                step=1,
            )

            estimated_salary = st.number_input(
                "Estimated Salary",
                min_value=0.0,
                value=75000.0,
                step=1000.0,
                format="%.2f",
            )

        with account_col2:
            has_credit_card = st.selectbox(
                "Has Credit Card?",
                options=["Yes", "No"],
            )

            is_active_member = st.selectbox(
                "Active Member?",
                options=["Yes", "No"],
            )

        submitted = st.form_submit_button(
            "Predict Churn Risk",
            type="primary",
            use_container_width=True,
        )

    # ---------------------------------------------------------
    # 3. Validate and generate prediction
    # ---------------------------------------------------------
    if submitted:

        customer_data = {
            "CreditScore": credit_score,
            "Age": age,
            "Tenure": tenure,
            "Balance": balance,
            "NumOfProducts": num_of_products,
            "EstimatedSalary": estimated_salary,
            "Geography": geography,
            "Gender": gender,
            "HasCrCard": int(has_credit_card == "Yes"),
            "IsActiveMember": int(is_active_member == "Yes"),
        }

        try:
            result = prediction_service.predict_one(customer_data)

        except (TypeError, ValueError) as exc:
            st.error(f"Invalid customer input: {exc}")
            return

        except Exception as exc:
            st.error(f"Prediction failed: {exc}")
            return

        render_prediction_result(
            result=result,
            threshold=threshold,
        )